from ...utils.logger import logger
from .download import Downloader
from .find import Finder


class BaseFileCollector:
    def __init__(self, config):
        """
        :param dictionary config: Config dictionary which contains environment settings like fsm ip, fam ip.
        """
        self._config = config
        self._finder = Finder()
        self._downloader = Downloader()

    def _download_files_via_ftp(self, ftp_params):
        for each in ftp_params:
            self._downloader.get_files_via_ftp(*each)

    def _download_files_via_ssh(self, ssh_params):
        for each in ssh_params:
            self._downloader.get_files_via_ssh(*each)

    def _retrieve_connection_params(self, dst_device):
        host = self._config[dst_device]["ip"]
        username = self._config[dst_device]["user"]
        password = self._config[dst_device]["pass"]
        return host, username, password


class WMPFileCollector(BaseFileCollector):
    """Collect files from BTS WMP needed by Reporting Portal such as SCFC or HWF."""

    def __init__(self, config):
        """
        :param dictionary config: Config dictionary which contains environment settings like fsm ip, fam ip.
        """
        super().__init__(config=config)

    def find_sw_version(self, path_dir, prefix=None):
        """Find software version based on TargetBD file available in path_dir.

        :param string path_dir: Path to directory where TargetBD file is available.
        :param string prefix:   BTS software load prefix e.g. LND0.0_ENB_.

        :note: Argument **prefix** is ignored by WMP products because TargetBD file contains all needed
        information in name.

        :return: BTS software version
        :rtype: string
        """
        logger.info("Finding the BTS software version")
        sw_version = self._finder.find_wmp_sw_version(path_dir, prefix)
        logger.debug(f"Found BTS sw version: {sw_version}")
        return sw_version

    def download_config_files(self, dest_dir):
        """Download configuration files from FSM.

        :param string dest_dir: Path to directory where downloaded files will be stored.
        """
        host, username, password = self._retrieve_connection_params("fsm")
        ssh_params = [
            [host, username, password, "/ffs/run/config/", "SCFC_.*.xml", dest_dir],
            [host, username, password, "/ffs/run/config/", "HWF.xml", dest_dir],
            [host, username, password, "/ffs/run/", "TargetBD.*.xml$", dest_dir],
        ]
        self._download_files_via_ftp(ssh_params)


class DCMFileCollector(BaseFileCollector):
    """
    A class to collect files from BTS DCM needed by Reporting Portal
    such as VersionInfo_RE.log or VersionInfo_REC.log.
    """

    def __init__(self, config):
        """
        :param dict config: Config dictionary which contains environment settings like fsm ip, fam ip.
        """
        super().__init__(config=config)

    def find_sw_version(self, path_dir, prefix=None):
        """Find software version based on TargetBD file available in path_dir.

        :param string path_dir: Path to directory where TargetBD file is available.
        :param string prefix:   BTS software load prefix e.g. LND0.0_ENB_.

        :return: BTS software version
        :rtype: string
        """
        logger.info("Finding the BTS software version")
        sw_version = self._finder.find_dcm_sw_version(path_dir, prefix)
        logger.debug(f"Found BTS sw version: {sw_version}")
        return sw_version

    def download_config_files(self, dest_dir):
        """Download configuration files from FSM.

        :param string dest_dir: Path to directory where downloaded files will be stored.
        """
        self._download_files_from_fam(dest_dir)
        self._download_files_from_fsm(dest_dir)

    def _download_files_from_fam(self, dest_dir):
        host, username, password = self._retrieve_connection_params("fam")
        ftp_params = [
            [
                host,
                username,
                password,
                "/fm/makerSpecific/",
                "VersionInfo_RE.log",
                dest_dir,
            ],
            [
                host,
                username,
                password,
                "/fm/makerSpecific/",
                "VersionInfo_REC.log",
                dest_dir,
            ],
        ]
        self._download_files_via_ftp(ftp_params)

    def _download_files_from_fsm(self, dest_dir):
        host, username, password = self._retrieve_connection_params("fsm")
        ftp_params = [
            [host, username, password, "/ffs/run/", "TargetBD.*.xml$", dest_dir],
        ]
        self._download_files_via_ftp(ftp_params)
